interface DiscountStrategy { Money apply(Sale s); }
class PercentOff implements DiscountStrategy {
  public Money apply(Sale s) { return s.getTotal().times(0.9); }
}
class Sale {
  private DiscountStrategy strategy; // Strategy + Polymorphism
  void setStrategy(DiscountStrategy d) { strategy = d; }
  Money getTotalAfterDiscount() { return strategy.apply(this); }
}

class Register {
  private ProductCatalog catalog;        // attribute visibility
  private Sale currentSale;
  public void enterItem(ItemID id, int qty) {  // id: parameter visibility
    ProductDescription desc = catalog.getProductDescription(id); // local
    currentSale.makeLineItem(desc, qty);
    Logger.getInstance().log("item");  // global via Singleton
  }
}
